 opt('#campaign-wall-story').onchange=e=>{if(busy)return;if(e.target.checked){c.wallStory=copy(STARBUCKS_STORY);delete c.journeyStory;c.visualStyle='coffee-integrated';c.direction='travel';if(c.seconds<6)c.seconds=24;if((c.unitSeconds||8)<6)c.unitSeconds=8;const other=c.installations.filter(i=>i.phase==='mural'&&i.enabled!==false&&i.screens.length!==6);for(const i of other)i.enabled=false;if(other.length)say(t('Excluido: ','Excluded: ')+other.map(i=>label(i.name)).join(', ')+t('. El relato bilingüe necesita seis pantallas.','. The bilingual story needs six screens.'));}else delete c.wallStory;fill();changed();};
