 for(const field of ['copy','lowerCopy'])for(const lang of ['es','en'])opt('#campaign-journey-'+(field==='lowerCopy'?'lower-':'')+lang).oninput=e=>{if(busy||!c.journeyStory)return;const count=c.journeyStory.copy[lang].length,lines=e.target.value.split('\n').map(v=>v.trim());if(lines.length!==count||lines.some(v=>!v||v.length>(field==='lowerCopy'?100:180))){say(t('Escribe una línea completa por pantalla.','Write one complete line per screen.'));return;}if(!c.journeyStory[field])c.journeyStory[field]=Object.fromEntries(['es','en'].map(l=>[l,Array.from({length:count},(_,n)=>COFFEE_JOURNEY[field][l][n%7])]));c.journeyStory[field][lang]=lines;changed();};
 for(const lang of ['es','en'])opt('#campaign-story-'+lang).oninput=e=>{if(busy||!c.wallStory)return;const blocks=e.target.value.trim().split(/\n\s*\n/).map(b=>b.split('\n').map(s=>s.trim()));if(blocks.length!==3||blocks.some(b=>b.length!==3||b.some(s=>!s||s.length>180))){say(t('Completa tres bloques de tres líneas para guardar el relato.','Complete three blocks of three lines to save the story.'));return;}blocks.forEach((b,n)=>c.wallStory.acts[n][lang]=b);changed();};
 options.querySelectorAll('[data-field]').forEach(el=>el.oninput=()=>{if(busy)return;const field=el.dataset.field;if(String(c[field])===el.value)return;if(field==='seconds'||field==='unitSeconds'){const n=Number(el.value);if(!Number.isInteger(n)||n<1||n>60){el.value=c.seconds;return;}c[field]=n;if(c.creationRequest&&field==='seconds')c.unitSeconds=n;}else{if(field==='headline'&&!el.value.trim()){el.value=c[field];return;}c[field]=el.value;}if(['headline','cta','price'].includes(field)&&c.headline.trim())c.translationDraft=false;changed();});
