 $('#campaign-approve').onclick=()=>{const i=installation();if(travelOwner!==i.id){stopTravel();travelTime=c.visualStyle==='coffee-integrated'?2:0;travelOwner=i.id;travelStarted=false;}travelTime=Math.min(travelTime,i.phase==='unit'?(c.unitSeconds||8):c.seconds);const p=checkedPlan(c,i,c.direction,measure);if(ready&&p.valid){approvals[key(i)]={revision:c.revision,direction:c.direction,reviewedAt:new Date().toISOString()};void persist();render();}};
