     try{png=await blob(cv);}finally{cv.width=cv.height=0;}
     const name=`${snapshot.id}-${i.id}-${snapshot.direction}-${s.id}-r${snapshot.revision}${contentLanguage(snapshot)==='en'?'-en':''}-${width}x${height}.png`;
     if(kind==='package'&&outputKind==='png'){
      const item=queue.addReady({label:`${snapshot.name} · ${label(i.name)} · ${s.id}`,sub:`${width}×${height} · PNG · r${snapshot.revision}`,campaign:{revision:snapshot.revision,contentLanguage:contentLanguage(snapshot),installation:i.id,screen:s.id,direction:snapshot.direction,contract,name:snapshot.name}},[{blob:png,filename:name,output:{W:width,H:height}}]);request.items.push(item);
     }else if(kind==='png')files[name]=new Uint8Array(await png.arrayBuffer());
     else if(kind==='stock-png'){
      const derived=contract.derived.find(d=>d.installation===i.id&&d.screen===s.id),
       composition=campaignComposition(snapshot,i,s,checkedPlan(snapshot,i,snapshot.direction,measure),{mediaType:'image'}),
       result=await publishAdaptation(png,{type:'image',title:`${snapshot.name} · ${i.id} · ${s.id} · ${snapshot.direction} · r${snapshot.revision}`,originId:`${snapshot.id}:r${snapshot.revision}`,client:snapshot.client||null,format:i.id,width,height,still:true},{
        tags:snapshot.creationRequest?.eink?einkStockTags(snapshot,i):['adaptación','imagen-fija','creador',...derived.tags],externalRef:`${snapshot.id}:r${snapshot.revision}`,composition,
        comment:JSON.stringify({schema:DEFAULT_CAMPAIGN.schema,campaign:snapshot.id,revision:snapshot.revision,contentLanguage:contentLanguage(snapshot),installation:i.id,screen:s.id,direction:snapshot.direction,...(snapshot.creationRequest?.eink?{eink:snapshot.creationRequest.eink}:{} )})
       });
      if(!result.ok)throw Error(result.error||'stock');
     }else{
      const job=campaignJob(snapshot,i,s,checkedPlan(snapshot,i,snapshot.direction,measure));if(job.kind==='animated-travel'){const product=document.createElement('canvas');product.width=assets.product.naturalWidth;product.height=assets.product.naturalHeight;product.getContext('2d').drawImage(assets.product,0,0);job.extraFiles=[{name:'product.png',url:URL.createObjectURL(await blob(product))}];product.width=product.height=0;}if(job.kind==='animated-integrated'){const files=job.layers.map((l,n)=>({name:`layer-${n}.png`,canvas:integratedLayerCanvas(l,snapshot,assets)}));if(job.mural)files.unshift({name:'product.png',canvas:integratedProductCanvas(snapshot,i,assets,travelGeometry(i,snapshot))});if(job.steam)files.splice(1,0,{name:'steam.png',canvas:steamAtlas()});job.extraFiles=[];for(const f of files){job.extraFiles.push({name:f.name,url:URL.createObjectURL(await blob(f.canvas))});f.canvas.width=f.canvas.height=0;}}const item=queue.add({label:`${snapshot.name} · ${(job.contentLanguages||[contentLanguage(snapshot)]).join(' / ').toUpperCase()} · ${label(i.name)} · ${s.id}`,sub:`${job.W}×${job.H} · ${job.durationSeconds} s · r${snapshot.revision}`,sourceURL:URL.createObjectURL(png),job,campaign:{revision:snapshot.revision,contentLanguage:contentLanguage(snapshot),installation:i.id,screen:s.id,direction:snapshot.direction,contract,name:snapshot.name,seconds:job.durationSeconds,screenContentLanguages:job.contentLanguages,animated:!!job.kind?.startsWith('animated-')}});exportItems.push(item);if(request)request.items.push(item);
     }
