 function updateDelivery(exportable=deliveryExportable){
  deliveryExportable=exportable;
  const button=$('#campaign-delivery-prepare'),status=$('#campaign-delivery-status'),list=$('#campaign-delivery-files');
  if(!deliveryRun){button.disabled=busy||!exportable;status.textContent=exportable?t('Todas las piezas incluidas están aprobadas. Puedes preparar la entrega.','All included pieces are approved. You can prepare the delivery.'):t('Revisa y aprueba todas las piezas incluidas antes de preparar la entrega.','Review and approve all included pieces before preparing the delivery.');list.replaceChildren();return;}
  const run=deliveryRun,check=inspectDelivery(run.plan,run.items),active=run.building||run.packaging||check.rows.some(r=>['queued','running'].includes(r.state));
  const same=run.source===JSON.stringify(c),states={done:t('Listo','Ready'),missing:t('Pendiente','Pending'),queued:t('En cola','Queued'),running:t('Preparando','Preparing'),error:t('Error: reintentar','Failed: retry'),cancelled:t('Cancelado: reintentar','Cancelled: retry'),invalid:t('Archivo no válido: reintentar','Invalid file: retry'),duplicate:t('Salida duplicada','Duplicate output')};
  status.textContent=`${run.plan.name} · r${run.plan.revision} · ${check.done}/${check.total} ${t('archivos listos','files ready')}`+(run.packaging?' · '+t('Empaquetando…','Packaging…'):run.error?' · '+run.error:run.downloaded?' · '+t('Entrega descargada','Delivery downloaded'):'');
  list.replaceChildren(...check.rows.map(row=>{const li=document.createElement('li');li.textContent=`${row.installation} / ${row.screen} / ${row.languages.join(' + ').toUpperCase()} · ${row.width}×${row.height} · ${row.kind.toUpperCase()} · ${states[row.state]||states.missing}`;return li;}));
  button.disabled=busy||active||(!check.complete&&(!same||!exportable));
  button.textContent=check.complete?t('Descargar entrega completa','Download complete delivery'):t('Reintentar archivos pendientes','Retry pending files');
  if(!same&&!active){button.disabled=busy||!exportable;button.textContent=t('Preparar entrega de la campaña actual','Prepare current campaign delivery');}
 }
 async function finishDelivery(run){
  if(!run||run.building||run.packaging||!run.auto||!inspectDelivery(run.plan,run.items).complete)return;
  run.packaging=true;run.auto=false;run.error='';updateDelivery();
  try{const {entries}=await deliveryEntries(run.plan,run.items,run.contract),{zipSync}=await loadZip();download(new Blob([zipSync(entries,{level:0})],{type:'application/zip'}),`${run.plan.campaignId}-entrega-r${run.plan.revision}.zip`);run.downloaded=true;}
  catch{run.error=t('No se pudo descargar el ZIP. Los archivos siguen disponibles para reintentar.','ZIP download failed. Files remain available to retry.');}
  finally{run.packaging=false;render();}
 }
 $('#campaign-delivery-prepare').onclick=async()=>{
  if(busy||!ready)return;
  try{
   const source=JSON.stringify(c),plan=deliveryPlan(c);
   if(!deliveryRun||deliveryRun.source!==source){
    const reusable=plan.rows.map(row=>exportItems.find(item=>deliveryItemMatches(row,item)&&['done','queued','running'].includes(item.state))).filter(Boolean);
    deliveryRun={source,plan,contract:campaignContract(portable(),approvals),items:reusable,building:false,packaging:false,auto:false};
   }
   const run=deliveryRun;run.error='';run.downloaded=false;
   if(inspectDelivery(run.plan,run.items).complete){run.auto=true;await finishDelivery(run);return;}
   const usable=new Set(inspectDelivery(run.plan,run.items).rows.filter(r=>['done','queued','running'].includes(r.state)).map(r=>r.key));
   run.items=run.items.filter(item=>usable.has(deliveryItemKey(item)));
   await deliver('package',run);
  }catch{say(t('No se pudo preparar la entrega. Revisa los idiomas y formatos.','Delivery could not be prepared. Check languages and formats.'));}
 };
