 $('#campaign-program').onclick=async()=>{if(busy||!exportItems.length||!exportItems.every(i=>i.state==='done'))return;const entries={'campaign.json':new TextEncoder().encode(JSON.stringify(campaignContract(portable(),approvals),null,2))},programs={};for(const variant of campaignVariants(c)){const records=exportItems.filter(i=>i.campaign.contentLanguage===contentLanguage(variant)).flatMap(i=>i.files.map(f=>({installation:i.campaign.installation,screen:i.campaign.screen,filename:f.filename}))),layouts=mixedPrograms(variant,records);programs[contentLanguage(variant)]=[];for(const {installation,program} of layouts){const name=layouts.length===1?(contentLanguages(c).length===1?'playlist-mixta.json':'playlist-mixta-'+contentLanguage(variant)+'.json'):'playlist-mixta-'+installation+'-'+contentLanguage(variant)+'.json';entries[name]=new TextEncoder().encode(JSON.stringify(program,null,2));programs[contentLanguage(variant)].push({installation,file:name});}}if(contentLanguages(c).length>1||Object.values(programs).some(rows=>rows.length>1))entries['programs.json']=new TextEncoder().encode(JSON.stringify({schema:'admira.multilingual-screen-program.v1',contentLanguages:contentLanguages(c),programs},null,2));for(const i of exportItems)for(const f of i.files)entries[f.filename]=new Uint8Array(await f.blob.arrayBuffer());const {zipSync}=await loadZip();download(new Blob([zipSync(entries,{level:0})],{type:'application/zip'}),c.id+'-playlist-mixta-r'+c.revision+'-'+contentLanguages(c).join('-')+'.zip');};
